(x, y, t) => {
  const cx = 240, cy = 120;
  const wx = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10 + Math.sin((x+y)*0.01+t*0.5)*8;
  const wy = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10 + Math.cos((x-y)*0.012-t*0.4)*7;
  const sx = x+wx, sy = y+wy;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 0.5],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.6],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 0.4],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.7],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 0.35],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.55],
    [80+Math.sin(t*0.7+3)*60, 40+Math.cos(t*0.3+2)*40, 0.14, 2.1, 0.45],
    [400+Math.cos(t*0.45+1)*70, 200+Math.sin(t*0.65+4)*50, 0.055, 2.4, 0.65]
  ];
  let aS=0, iS=0, dS=0;
  for(const [sX,sY,f,sp,w] of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const att=Math.exp(-d*0.003);
    aS+=Math.sin(d*f-t*sp)*w*att;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*w*att;
    dS+=Math.cos(d*f*0.5-t*sp*0.4+3.0)*w*0.5*att;
  }
  aS/=8; iS/=8; dS/=8;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    +Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2
    +Math.sin(sx*0.065+t*1.8)*Math.sin(sy*0.055-t*1.3)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4
    +Math.sin(dist*0.08+ang*2-t*2.2)*0.15;
  const diffusion=Math.tanh((aS-iS*0.7+dS*0.3)*1.5);
  const reaction=Math.tanh((aS-iS*0.7+bg*0.3+spiral+diffusion*0.4)*2.2);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const micro=Math.sin(sx*0.3+t*3)*Math.sin(sy*0.28-t*2.5)*Math.sin((sx-sy)*0.2+t*1.7)*0.08;
  const pulse=1.0+Math.sin(t*0.4)*0.1+Math.sin(t*0.7+1)*0.05;
  const blend=(reaction*0.6+cell*0.2+diffusion*0.15+micro)*pulse;
  const v=blend*0.5+0.5;
  const pal=[
    [4,12,52],[8,35,88],[12,65,115],[18,105,130],
    [30,150,135],[120,185,100],[200,190,60],
    [220,140,55],[210,90,60],[180,50,70],
    [120,30,75],[60,18,60],[4,12,52]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.8+Math.sin(reaction*Math.PI)*0.2;
  const edge=Math.abs(reaction)>0.65?1.12:1.0;
  const glow=Math.max(0,diffusion)*0.15;
  return [
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*40))|0,
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*60))|0,
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*80))|0
  ];
}
